const state = { view: 'projects', selected: [], createType: 'paper', results: [], tags: [], folders: [], folderProjectMap: {}, folderId: '', folderCopyProject: '', codexProject: '', codexRunId: '', codexTimer: null, folderCollapsed: new Set(), zoteroCollections: [], zoteroCollection: null, zoteroItems: [], zoteroSelected: new Set(), zoteroCollapsed: new Set() };
const $ = (s) => document.querySelector(s);
const esc = (s = '') => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const toast = (message) => { const el = $('#toast'); el.textContent = message; el.classList.add('show'); setTimeout(() => el.classList.remove('show'), 2600); };

async function api(path, options = {}) { const headers = options.body instanceof FormData ? {} : {'Content-Type':'application/json'}; const response = await fetch(path, { headers, ...options }); const data = await response.json(); if (!response.ok) throw new Error(data.error || '请求失败'); return data; }
function showView(view) { state.view = view; document.querySelectorAll('.view').forEach(el => el.classList.toggle('hidden', el.id !== `${view}-view`)); document.querySelectorAll('.nav-item').forEach(el => el.classList.toggle('active', el.dataset.view === view)); $('#page-title').textContent = view === 'projects' ? '项目' : view === 'zotero' ? 'Zotero 库' : view === 'create' ? '创建项目' : '任务队列'; $('#eyebrow').textContent = view === 'projects' ? 'WORKSPACES' : view === 'zotero' ? 'ZOTERO LIBRARY' : view.toUpperCase(); if (view === 'projects') renderProjects(); if (view === 'zotero') loadFolders().then(() => renderZotero()).catch(() => renderZotero()); if (view === 'create') loadFolders().then(() => renderCreate()).catch(() => renderCreate()); if (view === 'tasks') renderTasks(); }
function projectTags(tags = []) { return tags.map(tag => `<span class="tag">${esc(tag)}</span>`).join(''); }
function codexButton(name) { return `<button class="icon-button run-codex" data-name="${esc(name)}" title="在项目目录调用 Codex">✦ Codex</button>`; }

function folderName(folderId) { return (state.folders.find(folder => folder.id === folderId) || {}).name || ''; }
function folderOptions(selected = []) { const selectedSet = new Set(selected); const children = parentId => state.folders.filter(folder => (folder.parent_id || '') === (parentId || '')).sort((a, b) => a.name.localeCompare(b.name)).map(folder => `<option value="${esc(folder.id)}" ${selectedSet.has(folder.id) ? 'selected' : ''}>${esc('　'.repeat(folderDepth(folder.id)) + folder.name)}</option>${children(folder.id)}`).join(''); return children(null); }
function folderDepth(folderId) { let depth = 0; let current = state.folders.find(folder => folder.id === folderId); const seen = new Set(); while (current?.parent_id && !seen.has(current.parent_id)) { seen.add(current.parent_id); depth += 1; current = state.folders.find(folder => folder.id === current.parent_id); } return depth; }
function renderFolderTree() { const target = $('#folder-tree'); if (!target) return; const counts = state.folderCounts || {}; const byParent = parentId => state.folders.filter(folder => (folder.parent_id || '') === (parentId || '')).sort((a, b) => a.name.localeCompare(b.name)); const render = (parentId, depth = 0) => byParent(parentId).map(folder => { const children = byParent(folder.id); const collapsed = state.folderCollapsed.has(folder.id); return `<div class="folder-node"><div class="folder-row ${state.folderId === folder.id ? 'active' : ''}" style="--tree-depth:${depth}"><button class="folder-toggle ${children.length ? '' : 'is-empty'}" data-folder-id="${esc(folder.id)}" aria-expanded="${!collapsed}" title="${children.length ? (collapsed ? '展开目录' : '收起目录') : '没有子目录'}">${children.length ? (collapsed ? '›' : '⌄') : '·'}</button><button class="folder-label" data-folder-id="${esc(folder.id)}">${esc(folder.name)}</button><span class="folder-count">${counts[folder.id] || 0}</span><span class="folder-tools"><button class="folder-child" data-folder-id="${esc(folder.id)}" title="新建子文件夹">＋</button><button class="folder-copy-projects" data-folder-id="${esc(folder.id)}" title="复制此目录中的项目">⇢</button><button class="folder-rename" data-folder-id="${esc(folder.id)}" title="重命名">✎</button><button class="folder-delete" data-folder-id="${esc(folder.id)}" title="删除">×</button></span></div>${children.length ? `<div class="folder-children ${collapsed ? 'is-collapsed' : ''}">${render(folder.id, depth + 1)}</div>` : ''}</div>`; }).join(''); target.innerHTML = `<div class="folder-row folder-root-row ${state.folderId === '' ? 'active' : ''}"><button class="folder-toggle is-empty">·</button><button class="folder-label" data-folder-id="">全部项目</button><span class="folder-count">${state.projectsCount || 0}</span></div><div class="folder-row folder-root-row ${state.folderId === '__unfiled__' ? 'active' : ''}"><button class="folder-toggle is-empty">·</button><button class="folder-label" data-folder-id="__unfiled__">未分类</button><span class="folder-count">${state.unfiledCount || 0}</span></div>${state.folders.length ? `<div class="folder-tree-branch">${render(null)}</div>` : '<div class="folder-empty">暂无文件夹</div>'}`; target.querySelectorAll('.folder-toggle:not(.is-empty)').forEach(button => button.addEventListener('click', event => { event.stopPropagation(); const id = button.dataset.folderId; state.folderCollapsed.has(id) ? state.folderCollapsed.delete(id) : state.folderCollapsed.add(id); renderFolderTree(); })); target.querySelectorAll('.folder-label').forEach(button => button.addEventListener('click', () => { state.folderId = button.dataset.folderId; if (state.view !== 'projects') showView('projects'); else renderProjects(); })); target.querySelectorAll('.folder-child').forEach(button => button.addEventListener('click', event => { event.stopPropagation(); createFolder(button.dataset.folderId); })); target.querySelectorAll('.folder-copy-projects').forEach(button => button.addEventListener('click', event => { event.stopPropagation(); openFolderBulkCopy(button.dataset.folderId); })); target.querySelectorAll('.folder-rename').forEach(button => button.addEventListener('click', event => { event.stopPropagation(); renameFolder(button.dataset.folderId); })); target.querySelectorAll('.folder-delete').forEach(button => button.addEventListener('click', event => { event.stopPropagation(); removeFolder(button.dataset.folderId); })); }
async function loadFolders() { const data = await api('/api/folders'); state.folders = data.folders || []; state.folderProjectMap = data.project_folders || {}; state.folderCounts = data.counts || {}; renderFolderTree(); return data; }
async function createFolder(parentId = '') { const name = window.prompt(parentId ? '子文件夹名称' : '文件夹名称'); if (!name?.trim()) return; try { await api('/api/folders', {method:'POST', body:JSON.stringify({action:'create', name:name.trim(), parent_id:parentId || null})}); toast('文件夹已创建'); await loadFolders(); if (state.view === 'projects') renderProjects(); } catch (error) { toast(error.message); } }
async function renameFolder(id) { const current = folderName(id); const name = window.prompt('新的文件夹名称', current); if (!name?.trim() || name.trim() === current) return; try { await api('/api/folders', {method:'POST', body:JSON.stringify({action:'rename', id, name:name.trim()})}); toast('文件夹已重命名'); await loadFolders(); if (state.view === 'projects') renderProjects(); } catch (error) { toast(error.message); } }
async function removeFolder(id) { const current = folderName(id); if (!window.confirm(`删除文件夹“${current}”？项目不会被删除，子文件夹和项目归属会移动到它的上级目录。`)) return; try { await api('/api/folders', {method:'POST', body:JSON.stringify({action:'delete', id})}); if (state.folderId === id) state.folderId = ''; toast('文件夹已删除'); await loadFolders(); if (state.view === 'projects') renderProjects(); } catch (error) { toast(error.message); } }
async function createFolderFromCreate() { await createFolder(); await loadFolders(); const select = $('#project-folders'); if (select) select.innerHTML = folderOptions([...select.selectedOptions].map(option => option.value)); }
function renderFolderCopyOptions(excluded = [], selected = []) { const excludedSet = new Set(excluded); const selectedSet = new Set(selected); return state.folders.filter(folder => !excludedSet.has(folder.id)).map(folder => `<label class="folder-copy-option"><input type="checkbox" value="${esc(folder.id)}" ${selectedSet.has(folder.id) ? 'checked' : ''} /><span>${esc('　'.repeat(folderDepth(folder.id)) + folder.name)}</span><small>${state.folderCounts?.[folder.id] || 0} 个项目</small></label>`).join(''); }
function openFolderCopy(name, selected = []) { state.folderCopyMode = 'project'; state.folderCopyProject = name; state.folderCopySource = ''; const target = $('#folder-copy-list'); $('#folder-copy-description').textContent = `将“${name}”复制到选中的文件夹；已有归类会保留。`; target.innerHTML = state.folders.length ? renderFolderCopyOptions([], selected) : '<div class="folder-empty">暂无文件夹，请先创建一个文件夹。</div>'; $('#folder-copy-modal').classList.remove('hidden'); }
function openFolderBulkCopy(sourceId) { state.folderCopyMode = 'folder'; state.folderCopySource = sourceId; state.folderCopyProject = ''; const target = $('#folder-copy-list'); $('#folder-copy-description').textContent = `将“${folderName(sourceId)}”中的项目复制到选中的文件夹；源目录归类会保留。`; target.innerHTML = state.folders.length > 1 ? renderFolderCopyOptions([sourceId]) : '<div class="folder-empty">暂无其他文件夹，请先创建一个目标文件夹。</div>'; $('#folder-copy-modal').classList.remove('hidden'); }
async function saveFolderCopy() { const folderIds = [...document.querySelectorAll('#folder-copy-list input:checked')].map(input => input.value); if (!folderIds.length) { toast('请选择至少一个目标文件夹'); return; } try { if (state.folderCopyMode === 'folder') { const result = await api('/api/folders', {method:'POST', body:JSON.stringify({action:'copy-projects', source_id:state.folderCopySource, target_ids:folderIds})}); toast(`已复制 ${result.project_count} 个项目到目标文件夹`); } else { await api('/api/project/folders', {method:'POST', body:JSON.stringify({project:state.folderCopyProject, folder_ids:folderIds, mode:'add'})}); toast('项目已复制到选中文件夹'); } $('#folder-copy-modal').classList.add('hidden'); await loadFolders(); if (state.view === 'projects') renderProjects(); } catch (error) { toast(error.message); } }

async function renderProjects() {
  const [data, folderData] = await Promise.all([api('/api/projects'), loadFolders()]);
  state.projectsCount = data.projects.length;
  state.unfiledCount = data.projects.filter(project => !(project.folder_ids || []).length).length;
  state.folderCounts = folderData.counts || {};
  renderFolderTree();
  const view = $('#projects-view');
  const sort = state.projectSort || 'updated-desc';
  const visible = data.projects.filter(project => state.folderId === '' ? true : state.folderId === '__unfiled__' ? !(project.folder_ids || []).length : (project.folder_ids || []).includes(state.folderId));
  const sorted = [...visible].sort((a, b) => {
    if (sort === 'name-asc') return String(a.name || '').localeCompare(String(b.name || ''));
    if (sort === 'name-desc') return String(b.name || '').localeCompare(String(a.name || ''));
    if (sort === 'count-desc') return (b.article_count || 1) - (a.article_count || 1);
    if (sort === 'created-asc') return String(a.created_at || '').localeCompare(String(b.created_at || ''));
    if (sort === 'created-desc') return String(b.created_at || '').localeCompare(String(a.created_at || ''));
    return String(b.updated_at || '').localeCompare(String(a.updated_at || ''));
  });
  view.innerHTML = `<div class="toolbar"><div class="search"><input id="project-filter" placeholder="筛选项目..." /></div><div style="display:flex;align-items:center;gap:10px"><select id="project-sort" class="sort-select"><option value="updated-desc">最近修改</option><option value="created-desc">创建时间（新到旧）</option><option value="created-asc">创建时间（旧到新）</option><option value="name-asc">名称（A-Z）</option><option value="name-desc">名称（Z-A）</option><option value="count-desc">文章数（多到少）</option></select><span class="muted">${data.projects.length} 个项目</span></div></div><div class="panel project-list"><div class="project-row header"><span>项目</span><span>类型</span><span>文章</span><span>状态</span><span></span></div>${sorted.length ? sorted.map(p => {
    const status = p.processing?.status || 'ready';
    const codexRunning = p.codex_status === 'running';
    const statusLabel = codexRunning ? 'Codex 执行中' : status === 'needs_retry' ? '待重试' : status === 'failed' ? '失败' : '已就绪';
    const name = p.name || p.citation_key;
    const projectFolders = (p.folders || []).map(folder => folder.name).join(' · ');
    return `<div class="project-row"><div class="project-name"><div class="project-icon">${p.project_type === 'collection' ? '⌘' : 'P'}</div><div><button class="project-title-button show-details" data-name="${esc(name)}">${esc(name)}</button><small>${projectTags(p.tags)} ${projectFolders ? ` · ${esc(projectFolders)}` : ''} ${p.created_at ? `创建于 ${esc(p.created_at.slice(0,10))}` : ''}</small></div></div><span class="muted">${p.project_type === 'collection' ? '多篇' : '单篇'}</span><span class="muted">${p.article_count || 1}</span><span class="status ${codexRunning ? 'running' : esc(status)}">${statusLabel}</span><div class="row-actions"><button class="icon-button run-codex" data-name="${esc(name)}" title="调用 Codex">✦ Codex</button><button class="icon-button open-vscode" data-path="${esc(p.path || '')}" title="在 VS Code 中打开">⌘ VS Code</button><button class="icon-button project-more" data-name="${esc(name)}" title="更多项目操作">⋯ 其他</button></div></div>`;
  }).join('') : `<div class="empty"><strong>${state.folderId ? '这个文件夹里还没有项目' : '还没有项目'}</strong><span>从 Zotero 搜索或拖入 PDF，创建第一个阅读工作区。</span><br/><button class="primary-button" id="empty-create" style="margin-top:16px">＋ 创建项目</button></div>`}</div>`;
  $('#project-sort').value = sort;
  $('#project-sort').addEventListener('change', event => { state.projectSort = event.target.value; renderProjects(); });
  $('#project-filter')?.addEventListener('input', event => { document.querySelectorAll('.project-row:not(.header)').forEach(row => { row.style.display = row.textContent.toLowerCase().includes(event.target.value.toLowerCase()) ? '' : 'none'; }); });
  document.querySelectorAll('.open-vscode').forEach(btn => btn.addEventListener('click', () => openVSCode(btn.dataset.path)));
  document.querySelectorAll('.show-details').forEach(btn => btn.addEventListener('click', () => showProjectDetails(btn.dataset.name)));
  document.querySelectorAll('.project-more').forEach(btn => btn.addEventListener('click', () => showProjectDetails(btn.dataset.name)));
  document.querySelectorAll('.retry-project').forEach(btn => btn.addEventListener('click', async () => { try { await api('/api/retry', {method:'POST', body:JSON.stringify({name:btn.dataset.name})}); toast('已重新加入任务队列'); showView('tasks'); } catch (error) { toast(error.message); } }));
  $('#empty-create')?.addEventListener('click', () => showView('create'));
}
async function openVSCode(path) { try { await api('/api/open-vscode', {method:'POST', body:JSON.stringify({path})}); toast('已请求 VS Code 打开项目'); } catch (error) { toast(error.message); } }
async function openFinder(name) { try { await api('/api/open-finder', {method:'POST', body:JSON.stringify({name})}); toast('已在 Finder 中定位项目'); } catch (error) { toast(error.message); } }
const DEFAULT_CODEX_PROMPT = '使用 $paper-reading-zh 这个 skill 来阅读 full.md 以及 images/ 并撰写 markdown 报告输出到 outputs/ 中，标题使用论文标题的中文总结';
function openCodex(name, runId = '') { state.codexProject = name; state.codexRunId = runId; $('#codex-title').textContent = `调用 Codex：${name}`; $('#codex-prompt').value = DEFAULT_CODEX_PROMPT; $('#codex-status').textContent = runId ? '正在恢复任务记录…' : '后台非交互执行，工作目录固定为当前项目；请只让 Codex 修改项目内文件。'; $('#codex-log').textContent = ''; $('#codex-command-field').classList.toggle('hidden', !runId); $('#start-codex').classList.toggle('hidden', !!runId); $('#cancel-codex-run').classList.toggle('hidden', !runId); $('#codex-modal').classList.remove('hidden'); if (runId) pollCodex(); else setTimeout(() => $('#codex-prompt').focus(), 0); }
async function startCodex() { try { const run = await api('/api/codex/run', {method:'POST', body:JSON.stringify({project:state.codexProject, prompt:$('#codex-prompt').value})}); state.codexRunId = run.id; $('#start-codex').classList.add('hidden'); $('#cancel-codex-run').classList.remove('hidden'); pollCodex(); } catch (error) { toast(error.message); } }
async function pollCodex() { if (!state.codexRunId) return; try { const run = await api(`/api/codex/run?id=${encodeURIComponent(state.codexRunId)}`); const labels = {queued:'排队中',running:'执行中',cancelling:'正在取消',completed:'已完成',failed:'失败',cancelled:'已取消'}; $('#codex-status').textContent = `${labels[run.status] || run.status}${run.exit_code !== null && run.exit_code !== undefined ? ` · 退出码 ${run.exit_code}` : ''}`; $('#codex-log').textContent = run.log || ''; $('#codex-log').scrollTop = $('#codex-log').scrollHeight; if (['queued','running','cancelling'].includes(run.status)) { state.codexTimer = setTimeout(pollCodex, 1000); } else { $('#cancel-codex-run').classList.add('hidden'); $('#start-codex').classList.remove('hidden'); if (run.status === 'completed') { toast('Codex 执行完成'); renderProjects(); } else if (run.status === 'failed') toast('Codex 执行失败，请查看日志'); } } catch (error) { toast(error.message); } }
async function pollCodex() { if (!state.codexRunId) return; try { const run = await api(`/api/codex/run?id=${encodeURIComponent(state.codexRunId)}`); const labels = {queued:'排队中',running:'执行中',cancelling:'正在取消',completed:'已完成',failed:'失败',cancelled:'已取消',interrupted:'已中断'}; $('#codex-status').textContent = `${labels[run.status] || run.status}${run.exit_code !== null && run.exit_code !== undefined ? ` · 退出码 ${run.exit_code}` : ''}`; if (run.prompt) $('#codex-prompt').value = run.prompt; $('#codex-log').textContent = run.log || ''; $('#codex-log').scrollTop = $('#codex-log').scrollHeight; if (run.session_id) { $('#codex-command-field').classList.remove('hidden'); const command = await api(`/api/codex/command?id=${encodeURIComponent(state.codexRunId)}`); $('#codex-command').value = command.command; } if (['queued','running','cancelling'].includes(run.status)) { state.codexTimer = setTimeout(pollCodex, 1000); } else { $('#cancel-codex-run').classList.add('hidden'); $('#start-codex').classList.add('hidden'); if (run.status === 'completed') { toast('Codex 执行完成'); renderProjects(); } else if (run.status === 'failed') toast('Codex 执行失败，请查看日志'); } } catch (error) { toast(error.message); } }
async function cancelCodex() { if (!state.codexRunId) return; try { await api('/api/codex/cancel', {method:'POST', body:JSON.stringify({id:state.codexRunId})}); pollCodex(); } catch (error) { toast(error.message); } }
async function openOutput(name, path) { try { await api('/api/open-output', {method:'POST', body:JSON.stringify({project:name, path})}); toast('已使用默认应用打开产出'); } catch (error) { toast(error.message); } }
async function copyText(value, message = '已复制') { try { await navigator.clipboard.writeText(value); toast(message); } catch { const input = document.createElement('textarea'); input.value = value; document.body.append(input); input.select(); document.execCommand('copy'); input.remove(); toast(message); } }
async function showOutputs(name) { try { const data = await api(`/api/project/outputs?name=${encodeURIComponent(name)}`); $('#output-title').textContent = `产出文件：${name}`; $('#output-content').classList.add('hidden'); $('#output-list').innerHTML = data.outputs.length ? data.outputs.map(item => `<div class="output-item"><div><strong>${esc(item.path)}</strong><small>${esc(item.updated_at)} · ${Math.ceil(item.size / 1024)} KB</small></div><div class="output-actions"><button class="icon-button view-output" data-path="${esc(item.path)}">查看</button><button class="icon-button open-output" data-path="${esc(item.path)}">默认打开</button></div></div>`).join('') : '<div class="empty" style="padding:35px 10px"><strong>outputs/ 为空</strong><span>Codex 可以把阅读报告、比较结果等保存到这里。</span></div>'; $('#output-modal').classList.remove('hidden'); document.querySelectorAll('.view-output').forEach(btn => btn.addEventListener('click', async () => { try { const file = await api(`/api/output?project=${encodeURIComponent(name)}&path=${encodeURIComponent(btn.dataset.path)}`); $('#output-content').textContent = file.content; $('#output-content').classList.remove('hidden'); } catch (error) { toast(error.message); } })); document.querySelectorAll('.open-output').forEach(btn => btn.addEventListener('click', () => openOutput(name, btn.dataset.path))); } catch (error) { toast(error.message); } }
async function copyProjectPath(path) { try { await navigator.clipboard.writeText(path); toast('项目目录已复制'); } catch { const input = document.createElement('textarea'); input.value = path; document.body.append(input); input.select(); document.execCommand('copy'); input.remove(); toast('项目目录已复制'); } }
function openRename(name) { $('#rename-input').value = name; $('#rename-input').dataset.oldName = name; $('#rename-modal').classList.remove('hidden'); setTimeout(() => $('#rename-input').focus(), 0); }
async function saveRename() { const oldName = $('#rename-input').dataset.oldName; const newName = $('#rename-input').value.trim(); if (!newName) { toast('请输入项目名称'); return; } try { await api('/api/rename', {method:'POST', body:JSON.stringify({name:oldName, new_name:newName})}); $('#rename-modal').classList.add('hidden'); toast('项目名已更新'); renderProjects(); } catch (error) { toast(error.message); } }
async function removeProject(name) { if (!window.confirm(`确定删除项目“${name}”？\n项目目录和其中的阅读产物会被删除，原始 Zotero PDF 不受影响。`)) return; try { await api('/api/delete', {method:'POST', body:JSON.stringify({name})}); toast('项目已删除'); renderProjects(); } catch (error) { toast(error.message); } }
async function saveProjectFolders(name) { const picker = $('#detail-folder-picker'); if (!picker) return; const folderIds = [...picker.selectedOptions].map(option => option.value); try { await api('/api/project/folders', {method:'POST', body:JSON.stringify({project:name, folder_ids:folderIds})}); toast('项目文件夹已更新'); await loadFolders(); await showProjectDetails(name); } catch (error) { toast(error.message); } }
function renderFolderPicker(selected = [], detail = false) { return `<div class="folder-picker ${detail ? 'detail-folder-picker' : ''}"><label>${detail ? '所属文件夹' : '所属文件夹（可多选）'}</label><select id="${detail ? 'detail-folder-picker' : 'project-folders'}" class="folder-select" multiple>${folderOptions(selected)}</select><small class="muted">按住 Command 或 Ctrl 可选择多个文件夹</small>${detail ? '<button class="small-button folder-save" type="button">保存归类</button>' : ''}</div>`; }
async function showProjectDetails(name) { try { await loadFolders(); const details = await api(`/api/project?name=${encodeURIComponent(name)}`); renderProjectDetails(details); $('#project-modal').classList.remove('hidden'); } catch (error) { toast(error.message); } }
function renderProjectDetails(details) { const root = details.project; $('#detail-project-title').textContent = root.name || root.citation_key || '项目元数据'; const tabs = details.papers || []; const renderPaper = paper => { const meta = paper.metadata || {}; const fields = [['作者', meta.authors], ['年份 / 日期', meta.date], ['DOI', meta.doi], ['Citation key', paper.citation_key], ['来源 PDF', meta.path || root.source?.path], ['Zotero 条目', meta.zotero_item_key || meta.key]]; return `<div class="detail-grid">${fields.filter(([,value]) => value).map(([label,value]) => `<div class="detail-field"><label>${esc(label)}</label><div>${esc(value)}</div></div>`).join('')}</div><div class="detail-abstract"><h3>摘要</h3><p>${esc(meta.abstract || '未找到摘要。可在 full.md 中添加 Abstract 标题后重新打开此详情。')}</p></div><div class="artifact-list"><span class="artifact-state ${paper.full_exists?'ok':''}">${paper.full_exists?'✓':'○'} full.md</span><span class="artifact-state ${paper.translation_exists?'ok':''}">${paper.translation_exists?'✓':'○'} translation.md</span><span class="artifact-state ${paper.full_exists?'ok':''}">${paper.full_exists?'✓':'○'} images/</span><span class="artifact-state">outputs/</span></div>`; }; const selected = tabs[0]; $('#project-detail-content').innerHTML = `<div class="detail-toolbar"><div class="detail-path" title="${esc(details.path)}">${esc(details.path)}</div><div class="detail-actions"><button class="icon-button detail-codex">✦ Codex</button><button class="icon-button detail-outputs">▤ 产出</button><button class="icon-button detail-finder">⌂ Finder</button><button class="icon-button detail-copy-folder">⇢ 复制到文件夹</button><button class="icon-button detail-copy" data-path="${esc(details.path)}">▢ 复制目录</button><button class="icon-button detail-rename">✎ 重命名</button><button class="icon-button detail-delete">⌫ 删除</button></div></div>${renderFolderPicker(root.folder_ids || [], true)}${tabs.length > 1 ? `<div class="detail-tabs">${tabs.map((paper,index) => `<button class="detail-tab ${index===0?'active':''}" data-tab="${index}">${esc(paper.metadata?.title || paper.citation_key)}</button>`).join('')}</div>` : ''}<div id="detail-paper-content">${selected ? renderPaper(selected) : '<p class="muted">项目尚无文章详情。</p>'}</div><section class="codex-history"><div class="section-heading"><div><h3>Codex 任务</h3><p class="muted">查看这个项目之前完成或未完成的调用。</p></div><button class="icon-button refresh-codex-history">↻ 刷新</button></div><div id="codex-history-list"><div class="muted">加载中…</div></div></section>`; $('#project-detail-content').querySelector('.detail-copy')?.addEventListener('click', event => copyProjectPath(event.currentTarget.dataset.path)); $('#project-detail-content').querySelector('.detail-codex')?.addEventListener('click', () => openCodex(root.name)); $('#project-detail-content').querySelector('.detail-outputs')?.addEventListener('click', () => showOutputs(root.name)); $('#project-detail-content').querySelector('.detail-finder')?.addEventListener('click', () => openFinder(root.name)); $('#project-detail-content').querySelector('.detail-copy-folder')?.addEventListener('click', () => openFolderCopy(root.name, root.folder_ids || [])); $('#project-detail-content').querySelector('.detail-rename')?.addEventListener('click', () => { $('#project-modal').classList.add('hidden'); openRename(root.name); }); $('#project-detail-content').querySelector('.detail-delete')?.addEventListener('click', () => { $('#project-modal').classList.add('hidden'); removeProject(root.name); }); $('#project-detail-content').querySelector('.folder-save')?.addEventListener('click', () => saveProjectFolders(root.name)); $('#project-detail-content').querySelector('.refresh-codex-history')?.addEventListener('click', () => loadCodexHistory(root.name)); $('#project-detail-content').querySelectorAll('.detail-tab').forEach(btn => btn.addEventListener('click', () => { $('#project-detail-content').querySelectorAll('.detail-tab').forEach(tab => tab.classList.toggle('active', tab === btn)); $('#detail-paper-content').innerHTML = renderPaper(tabs[Number(btn.dataset.tab)]); })); loadCodexHistory(root.name); }

async function loadCodexHistory(name) { const target = $('#codex-history-list'); if (!target) return; try { const data = await api(`/api/project/codex-runs?name=${encodeURIComponent(name)}`); const labels = {queued:'排队中',running:'执行中',cancelling:'取消中',completed:'已完成',failed:'失败',cancelled:'已取消',interrupted:'已中断'}; target.innerHTML = data.runs.length ? data.runs.map(run => `<article class="codex-history-item"><div class="codex-history-head"><div><strong>${esc(run.created_at || 'Codex 调用')}</strong><span class="status ${esc(run.status)}">${labels[run.status] || run.status}</span></div><span class="muted">${run.outputs?.length || 0} 个产出</span></div><p class="codex-prompt-preview">${esc(run.prompt || '')}</p><div class="codex-history-actions"><button class="icon-button history-open" data-run="${esc(run.id)}">打开记录</button><button class="icon-button history-prompt" data-prompt="${esc(run.prompt || '')}">复制提示词</button>${run.command ? `<button class="icon-button history-command" data-command="${esc(run.command)}">复制终端指令</button>` : ''}${run.outputs?.length ? `<button class="icon-button history-output" data-name="${esc(name)}">查看输出</button>` : ''}</div></article>`).join('') : '<div class="empty" style="padding:28px 10px"><strong>暂无 Codex 任务</strong><span>从上方调用 Codex 后，记录会保存在这里。</span></div>'; target.querySelectorAll('.history-open').forEach(btn => btn.addEventListener('click', () => openCodex(name, btn.dataset.run))); target.querySelectorAll('.history-prompt').forEach(btn => btn.addEventListener('click', () => copyText(btn.dataset.prompt, '提示词已复制'))); target.querySelectorAll('.history-command').forEach(btn => btn.addEventListener('click', () => copyText(btn.dataset.command, '终端指令已复制'))); target.querySelectorAll('.history-output').forEach(btn => btn.addEventListener('click', () => showOutputs(btn.dataset.name))); } catch (error) { target.innerHTML = `<div class="muted">${esc(error.message)}</div>`; } }

function zoteroCollectionTree() { const roots = state.zoteroCollections.filter(item => !item.parent_id); const children = parent => state.zoteroCollections.filter(item => item.parent_id === parent).sort((a, b) => a.name.localeCompare(b.name)); const render = (items, depth = 0) => items.map(item => { const nested = children(item.id); const collapsed = state.zoteroCollapsed.has(item.key); return `<div class="zotero-node"><div class="zotero-collection-row ${state.zoteroCollection?.key === item.key ? 'active' : ''}" style="--tree-depth:${depth}"><button class="zotero-toggle ${nested.length ? '' : 'is-empty'}" data-key="${esc(item.key)}" aria-expanded="${!collapsed}" title="${nested.length ? (collapsed ? '展开 collection' : '收起 collection') : '没有子 collection'}">${nested.length ? (collapsed ? '›' : '⌄') : '·'}</button><button class="zotero-collection-label" data-key="${esc(item.key)}"><span class="zotero-folder-icon">${nested.length ? (collapsed ? '▸' : '▾') : '•'}</span><span class="zotero-collection-name">${esc(item.name)}</span><small>${item.item_count || 0}</small></button></div>${nested.length ? `<div class="zotero-children ${collapsed ? 'is-collapsed' : ''}">${render(nested, depth + 1)}</div>` : ''}</div>`; }).join(''); return render(roots); }
function bindZoteroCollectionTree() { const target = $('#zotero-collections'); if (!target) return; target.querySelectorAll('.zotero-toggle:not(.is-empty)').forEach(button => button.addEventListener('click', event => { event.stopPropagation(); const key = button.dataset.key; state.zoteroCollapsed.has(key) ? state.zoteroCollapsed.delete(key) : state.zoteroCollapsed.add(key); target.innerHTML = zoteroCollectionTree(); bindZoteroCollectionTree(); })); target.querySelectorAll('.zotero-collection-label').forEach(button => button.addEventListener('click', () => loadZoteroCollection(button.dataset.key))); }
function zoteroItemSelected(item) { return item.has_pdf && state.zoteroSelected.has(item.zotero_item_key); }
function renderZoteroItems() { const target = $('#zotero-items'); if (!target) return; const items = state.zoteroItems; target.innerHTML = items.length ? items.map(item => `<label class="zotero-item ${item.has_pdf ? '' : 'no-pdf'}"><input type="checkbox" data-item-key="${esc(item.zotero_item_key)}" ${zoteroItemSelected(item) ? 'checked' : ''} ${item.has_pdf ? '' : 'disabled'} /><div class="zotero-item-main"><strong>${esc(item.title || '未命名条目')}</strong><div class="zotero-item-meta">${esc(item.authors || '作者未知')} · ${esc(item.date || '日期未知')} ${item.doi ? `· DOI ${esc(item.doi)}` : ''}</div>${item.abstract ? `<p>${esc(item.abstract)}</p>` : ''}<div class="zotero-item-source">${item.has_pdf ? `${item.pdfs.length} 个 PDF 附件` : '没有可用 PDF 附件'}</div></div></label>`).join('') : '<div class="empty"><strong>这个 collection 没有直接条目</strong><span>子 collection 的条目不会混入当前列表。</span></div>'; target.querySelectorAll('input[data-item-key]').forEach(input => input.addEventListener('change', () => { if (input.checked) state.zoteroSelected.add(input.dataset.itemKey); else state.zoteroSelected.delete(input.dataset.itemKey); updateZoteroSelection(); })); }
function updateZoteroSelection() { const selected = state.zoteroItems.filter(item => state.zoteroSelected.has(item.zotero_item_key)); const count = selected.length; $('#zotero-selection-count').textContent = `${count} 篇已选择`; $('#zotero-select-all').checked = !!state.zoteroItems.filter(item => item.has_pdf).length && state.zoteroItems.filter(item => item.has_pdf).every(item => state.zoteroSelected.has(item.zotero_item_key)); $('#zotero-create').disabled = !count; }
async function loadZoteroCollection(key) { try { const data = await api(`/api/zotero/collection?key=${encodeURIComponent(key)}`); state.zoteroCollection = data.collection; state.zoteroItems = data.items || []; state.zoteroSelected = new Set(); $('#zotero-current-title').textContent = data.collection.name; $('#zotero-current-meta').textContent = `${data.direct_count} 篇直接条目 · ${data.pdf_count} 篇有本地 PDF · 不包含子目录`; $('#zotero-collections').innerHTML = zoteroCollectionTree(); document.querySelectorAll('.zotero-collection').forEach(button => button.addEventListener('click', () => loadZoteroCollection(button.dataset.key))); renderZoteroItems(); updateZoteroSelection(); } catch (error) { toast(error.message); } }
function zoteroPapers() { return state.zoteroItems.filter(item => state.zoteroSelected.has(item.zotero_item_key)).flatMap(item => item.pdfs.map(path => ({...item, path, title: item.title || path.split('/').pop()}))); }
async function createFromZotero() { const papers = zoteroPapers(); if (!papers.length) { toast('请选择至少一篇带 PDF 的文章'); return; } const mode = $('#zotero-create-mode').value; const tags = ($('#zotero-tags').value || '').split(',').map(x => x.trim()).filter(Boolean); const folderIds = [...($('#zotero-folders').selectedOptions || [])].map(option => option.value); const base = {tags, folder_ids: folderIds, translate: $('#zotero-translate').checked, auto_codex: $('#zotero-auto-codex').checked, codex_prompt: $('#zotero-codex-prompt').value.trim()}; try { if (mode === 'single') { for (const paper of papers) await api('/api/projects', {method:'POST', body:JSON.stringify({...base, project_type:'paper', name:'', papers:[paper]})}); } else { await api('/api/projects', {method:'POST', body:JSON.stringify({...base, project_type:'collection', name:$('#zotero-project-name').value.trim() || state.zoteroCollection.name, papers})}); } toast(`已加入 ${papers.length} 篇文章的处理任务`); showView('tasks'); } catch (error) { toast(error.message); } }
async function renderZotero() { const view = $('#zotero-view'); if (!view) return; view.innerHTML = '<div class="zotero-layout"><aside class="panel zotero-browser"><div class="zotero-browser-head"><div><h2>我的 Zotero</h2><p class="muted">选择一个 collection 查看其中的直接条目</p></div><button class="icon-button" id="zotero-refresh">↻</button></div><div id="zotero-collections" class="zotero-collections"><div class="muted">加载中...</div></div></aside><section class="zotero-content"><div class="zotero-content-head"><div><p class="eyebrow">DIRECT ITEMS</p><h2 id="zotero-current-title">选择 collection</h2><p id="zotero-current-meta" class="muted">不包含子目录中的文章</p></div><div class="zotero-head-actions"><button class="ghost-button" id="zotero-select-pdf">全选带 PDF</button><span id="zotero-selection-count" class="selection-count">0 篇已选择</span></div></div><div id="zotero-items" class="zotero-items"><div class="empty"><strong>从左侧选择一个 collection</strong><span>这里会列出该目录下的文章标题、作者、日期、DOI 和 PDF 状态。</span></div></div><div class="panel zotero-action-panel"><div class="zotero-action-head"><div><h3>创建阅读工作区</h3><p class="muted">所选文章会进入现有 PDF 提取、翻译和 Codex 流程。</p></div><label class="check"><input id="zotero-select-all" type="checkbox" /> 全选当前目录（仅直接条目）</label></div><div class="zotero-action-grid"><div class="field"><label>创建方式</label><select id="zotero-create-mode" class="sort-select"><option value="collection">合并为一个多文章项目</option><option value="single">逐个创建单篇项目</option></select></div><div class="field"><label>多文章项目名称</label><input id="zotero-project-name" placeholder="默认使用 collection 名称" /></div><div class="field"><label>工作区目录</label><select id="zotero-folders" class="folder-select" multiple>${folderOptions()}</select></div><div class="field"><label>项目标签</label><input id="zotero-tags" placeholder="例如：待读, SIGIR" /></div></div><div class="zotero-workflow-options"><label class="check"><input id="zotero-translate" type="checkbox" /> 同时生成中文翻译</label><label class="check"><input id="zotero-auto-codex" type="checkbox" /> 提取完成后自动执行 Codex</label></div><div class="field hidden" id="zotero-codex-field"><label>自动执行提示词</label><textarea id="zotero-codex-prompt" rows="3">${esc(DEFAULT_CODEX_PROMPT)}</textarea></div><div class="zotero-action-footer"><span class="muted">只处理有本地 PDF 附件的条目</span><button class="primary-button" id="zotero-create" disabled>加入处理队列</button></div></div></section></div>'; const load = async () => { try { const data = await api('/api/zotero/collections'); state.zoteroCollections = data.collections || []; $('#zotero-collections').innerHTML = state.zoteroCollections.length ? zoteroCollectionTree() : '<div class="folder-empty">没有找到 Zotero collection</div>'; document.querySelectorAll('.zotero-collection').forEach(button => button.addEventListener('click', () => loadZoteroCollection(button.dataset.key))); } catch (error) { $('#zotero-collections').innerHTML = `<div class="muted">${esc(error.message)}</div>`; } }; $('#zotero-refresh').addEventListener('click', renderZotero); $('#zotero-select-pdf').addEventListener('click', () => { state.zoteroSelected = new Set(state.zoteroItems.filter(item => item.has_pdf).map(item => item.zotero_item_key)); renderZoteroItems(); updateZoteroSelection(); }); $('#zotero-select-all').addEventListener('change', event => { state.zoteroSelected = event.target.checked ? new Set(state.zoteroItems.filter(item => item.has_pdf).map(item => item.zotero_item_key)) : new Set(); renderZoteroItems(); updateZoteroSelection(); }); $('#zotero-create-mode').addEventListener('change', event => $('#zotero-project-name').disabled = event.target.value === 'single'); $('#zotero-auto-codex').addEventListener('change', event => $('#zotero-codex-field').classList.toggle('hidden', !event.target.checked)); $('#zotero-create').addEventListener('click', createFromZotero); await load(); if (state.zoteroCollection) await loadZoteroCollection(state.zoteroCollection.key); }
function selectedFromPath(path) { return { path, title: path.split('/').pop().replace(/\.pdf$/i,''), citation_key: path.split('/').pop().replace(/\.pdf$/i,'').replace(/[^A-Za-z0-9]+(.)/g, (_, c) => c.toUpperCase()).replace(/[^A-Za-z0-9]/g,'').slice(0,80), abstract: '', authors: '', year: '' }; }
function renderCreate() { const view = $('#create-view'); view.innerHTML = `<div class="create-layout"><div class="panel create-card"><h2 class="card-title">选择文章</h2><p class="card-description">从 Zotero 找到本地附件，或添加任意 PDF。</p><div class="segmented"><button class="segment ${state.createType === 'paper' ? 'active':''}" data-type="paper">单篇文章</button><button class="segment ${state.createType === 'collection' ? 'active':''}" data-type="collection">多篇工作区</button></div><div class="search" style="margin-top:17px;max-width:none"><input id="zotero-search" placeholder="搜索标题、作者或 citation key" /></div><div id="search-results" class="search-results"><div class="empty" style="padding:22px 10px">输入标题开始搜索 Zotero</div></div><div class="dropzone" id="dropzone"><strong>拖拽 PDF 到这里</strong><span>支持 Zotero 之外的任意本地 PDF</span><label for="pdf-input">选择 PDF 文件</label><input id="pdf-input" type="file" accept="application/pdf,.pdf" multiple /></div><div class="path-row"><input class="path-input" id="manual-path" placeholder="或粘贴 PDF 绝对路径" /><button class="small-button" id="add-path">添加</button></div><div id="selected-list" class="selected-list"></div></div><div class="panel create-card"><h2 class="card-title">项目设置</h2><p class="card-description">处理结果将写入统一工作区目录。</p><div class="field"><label>项目名称</label><input id="project-name" placeholder="默认使用 citation key" /></div><div class="field"><label>项目标签</label><input id="project-tags" placeholder="例如：LTV, recommendation, 待读" /><small class="muted">使用逗号分隔多个标签</small></div><div class="field"><label>所属文件夹（可多选）</label><div class="folder-select-wrap"><select id="project-folders" class="folder-select" multiple>${folderOptions()}</select><button class="small-button folder-new" id="create-folder-inline" type="button" title="新建文件夹">＋ 新建</button></div><small class="muted">按住 Command 或 Ctrl 可选择多个文件夹</small></div><label class="check"><input id="translate" type="checkbox" /> 同时生成中文翻译</label><label class="check"><input id="auto-codex" type="checkbox" /> 提取完成后自动执行 Codex</label><div class="field hidden" id="auto-codex-prompt-field"><label>自动执行提示词</label><textarea id="auto-codex-prompt" rows="4">${esc(DEFAULT_CODEX_PROMPT)}</textarea></div><button class="primary-button create-submit" id="create-submit">创建项目并加入任务队列</button><div class="meta-box"><h3>工作区位置</h3><div id="workspace-location" class="muted">加载中...</div></div></div></div>`; bindCreate(); renderSelected(); }
async function importFiles(files) { const pdfs = [...files].filter(file => file.name.toLowerCase().endsWith('.pdf')); if (!pdfs.length) return; const form = new FormData(); pdfs.forEach(file => form.append('files', file, file.name)); try { const result = await api('/api/import', {method:'POST', body:form}); state.selected.push(...result.files); renderSelected(); } catch (error) { toast(error.message); } }
function bindCreate() { document.querySelectorAll('.segment').forEach(btn => btn.addEventListener('click', () => { state.createType = btn.dataset.type; renderCreate(); })); let timer; $('#zotero-search').addEventListener('input', e => { clearTimeout(timer); timer = setTimeout(() => searchZotero(e.target.value), 250); }); $('#pdf-input').addEventListener('change', e => importFiles(e.target.files)); const drop = $('#dropzone'); ['dragenter','dragover'].forEach(type => drop.addEventListener(type, e => { e.preventDefault(); drop.classList.add('dragover'); })); ['dragleave','drop'].forEach(type => drop.addEventListener(type, e => { e.preventDefault(); drop.classList.remove('dragover'); })); drop.addEventListener('drop', e => importFiles(e.dataTransfer.files)); $('#add-path').addEventListener('click', () => { const input = $('#manual-path'); if (!input.value.trim()) return; state.selected.push(selectedFromPath(input.value.trim())); input.value = ''; renderSelected(); }); $('#create-folder-inline')?.addEventListener('click', createFolderFromCreate); $('#auto-codex').addEventListener('change', e => $('#auto-codex-prompt-field').classList.toggle('hidden', !e.target.checked)); $('#create-submit').addEventListener('click', submitProject); api('/api/config').then(data => { $('#workspace-location').textContent = data.workspaces_dir; }).catch(() => {}); }
async function searchZotero(query) { if (!query.trim()) { $('#search-results').innerHTML = '<div class="empty" style="padding:22px 10px">输入标题开始搜索 Zotero</div>'; return; } const data = await api(`/api/search?q=${encodeURIComponent(query)}`); state.results = data.items; $('#search-results').innerHTML = data.items.length ? data.items.flatMap(item => (item.pdfs || []).map(path => `<label class="result"><input type="checkbox" data-path="${esc(path)}" /><div><div class="result-title">${esc(item.title || path)}</div><div class="result-meta">${esc(item.authors || '作者未知')} · ${esc(item.citation_key || '')} · ${esc(item.date || '')}</div><div class="result-meta" title="${esc(path)}">${esc(path)}</div>${item.doi ? `<div class="result-meta">DOI ${esc(item.doi)}</div>` : ''}${item.abstract ? `<div class="result-abstract">${esc(item.abstract)}</div>` : ''}</div><span class="muted">PDF</span></label>`)).join('') : '<div class="empty" style="padding:22px 10px">没有找到带 PDF 附件的结果</div>'; document.querySelectorAll('.result input').forEach(input => input.addEventListener('change', () => { const path = input.dataset.path; const item = state.results.find(row => (row.pdfs || []).includes(path)); if (input.checked) state.selected.push({...item, path, title:item.title || path.split('/').pop()}); else state.selected = state.selected.filter(row => row.path !== path); renderSelected(); })); }
function renderSelected() { const target = $('#selected-list'); if (!target) return; target.innerHTML = state.selected.length ? `<div class="muted" style="font-size:11px">已选择 ${state.selected.length} 个 PDF</div>` + state.selected.map((item, index) => `<div class="selected-item"><span class="project-icon" style="width:26px;height:26px;font-size:11px">PDF</span><div style="min-width:0"><strong style="display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(item.title || item.path)}</strong><small class="muted">${esc(item.citation_key || '')}</small>${item.abstract ? `<div class="abstract">${esc(item.abstract)}</div>` : ''}</div><button class="remove" data-index="${index}">×</button></div>`).join('') : ''; target.querySelectorAll('.remove').forEach(btn => btn.addEventListener('click', () => { state.selected.splice(Number(btn.dataset.index), 1); renderSelected(); })); }
async function submitProject() { if (!state.selected.length) { toast('请先选择或添加 PDF'); return; } const tags = $('#project-tags').value.split(',').map(x => x.trim()).filter(Boolean); const folderIds = [...($('#project-folders')?.selectedOptions || [])].map(option => option.value); try { const result = await api('/api/projects', {method:'POST', body:JSON.stringify({project_type:state.createType, name:$('#project-name').value.trim(), tags, folder_ids:folderIds, translate:$('#translate').checked, auto_codex:$('#auto-codex').checked, codex_prompt:$('#auto-codex-prompt').value.trim(), papers:state.selected})}); toast(`已创建 ${result.name}，任务已加入队列`); state.selected = []; showView('tasks'); } catch (error) { toast(error.message); } }

async function renderTasks() { const [data, config] = await Promise.all([api('/api/tasks'), api('/api/config')]); const view = $('#tasks-view'); const label = status => ({queued:'排队中',running:'处理中',cancelling:'正在取消',completed:'已完成',failed:'失败',cancelled:'已取消',interrupted:'已中断'}[status] || status); view.innerHTML = `<div class="toolbar"><span class="muted">PDF 提取并发：${config.concurrency} · Codex 并发：${config.codex_concurrency || 1}</span><button class="ghost-button" id="tasks-refresh">↻ 刷新</button></div><div class="task-list">${data.tasks.length ? data.tasks.map(task => `<div class="panel task-card ${task.task_type === 'codex' ? 'codex-task' : ''}" data-run-id="${esc(task.run_id || '')}" data-project="${esc(task.project_slug || '')}"><div class="task-head"><div><strong>${task.task_type === 'codex' ? '✦ ' : ''}${esc(task.paper_slug)}</strong><div class="task-message">${esc(task.message || '')}</div></div><span class="status ${esc(task.status)}">${label(task.status)}</span></div><div class="progress"><i style="width:${task.progress || 0}%"></i></div><div class="task-foot"><span>${esc(task.project_slug)}</span><span>${task.progress || 0}%</span></div></div>`).join('') : '<div class="empty panel"><strong>任务队列为空</strong><span>创建项目或调用 Codex 后，任务会显示在这里。</span></div>'}</div>`; $('#tasks-refresh').addEventListener('click', renderTasks); document.querySelectorAll('.codex-task').forEach(card => card.addEventListener('click', () => openCodex(card.dataset.project, card.dataset.runId))); }
async function refreshBadge() { const data = await api('/api/tasks'); const active = data.tasks.filter(t => ['queued','running','cancelling'].includes(t.status)).length; $('#task-badge').textContent = active; if (state.view === 'tasks') renderTasks(); }
async function openSettings() { const config = await api('/api/config'); $('#settings-zotero').value = config.zotero_dir; $('#settings-workspaces').value = config.workspaces_dir; $('#settings-concurrency').value = config.concurrency; $('#settings-codex-concurrency').value = config.codex_concurrency || 1; $('#settings-modal').classList.remove('hidden'); }
async function saveSettings() { try { await api('/api/config', {method:'POST', body:JSON.stringify({zotero_dir:$('#settings-zotero').value.trim(), workspaces_dir:$('#settings-workspaces').value.trim(), concurrency:Number($('#settings-concurrency').value), codex_concurrency:Number($('#settings-codex-concurrency').value)})}); $('#settings-modal').classList.add('hidden'); toast('设置已保存'); renderProjects(); } catch (error) { toast(error.message); } }
document.querySelectorAll('.nav-item').forEach(btn => btn.addEventListener('click', () => showView(btn.dataset.view))); $('#new-project-button').addEventListener('click', () => showView('create')); $('#refresh-button').addEventListener('click', () => state.view === 'projects' ? renderProjects() : state.view === 'tasks' ? renderTasks() : renderCreate()); $('#new-folder').addEventListener('click', () => createFolder()); $('#settings-button').addEventListener('click', openSettings); $('#close-settings').addEventListener('click', () => $('#settings-modal').classList.add('hidden')); $('#cancel-settings').addEventListener('click', () => $('#settings-modal').classList.add('hidden')); $('#save-settings').addEventListener('click', saveSettings); $('#close-project').addEventListener('click', () => $('#project-modal').classList.add('hidden')); document.querySelector('#project-modal .modal-backdrop').addEventListener('click', () => $('#project-modal').classList.add('hidden')); $('#close-rename').addEventListener('click', () => $('#rename-modal').classList.add('hidden')); $('#cancel-rename').addEventListener('click', () => $('#rename-modal').classList.add('hidden')); $('#save-rename').addEventListener('click', saveRename); document.querySelector('#rename-modal .modal-backdrop').addEventListener('click', () => $('#rename-modal').classList.add('hidden')); $('#start-codex').addEventListener('click', startCodex); $('#cancel-codex-run').addEventListener('click', cancelCodex); $('#copy-codex-command').addEventListener('click', () => copyProjectPath($('#codex-command').value)); $('#close-codex').addEventListener('click', () => $('#codex-modal').classList.add('hidden')); $('#cancel-codex').addEventListener('click', () => $('#codex-modal').classList.add('hidden')); document.querySelector('#codex-modal .modal-backdrop').addEventListener('click', () => $('#codex-modal').classList.add('hidden')); $('#close-output').addEventListener('click', () => $('#output-modal').classList.add('hidden')); document.querySelector('#output-modal .modal-backdrop').addEventListener('click', () => $('#output-modal').classList.add('hidden')); document.addEventListener('click', event => { const run = event.target.closest('.run-codex'); if (run) openCodex(run.dataset.name); const output = event.target.closest('.show-outputs'); if (output) showOutputs(output.dataset.name); }); setInterval(refreshBadge, 1600); showView('projects');
$('#close-folder-copy')?.addEventListener('click', () => $('#folder-copy-modal').classList.add('hidden')); $('#cancel-folder-copy')?.addEventListener('click', () => $('#folder-copy-modal').classList.add('hidden')); document.querySelector('#folder-copy-modal .modal-backdrop')?.addEventListener('click', () => $('#folder-copy-modal').classList.add('hidden')); $('#save-folder-copy')?.addEventListener('click', saveFolderCopy);
